/**
 * Base das visualizações 2D — porte de `componentes/viz/_canvas2d.js` do legado.
 *
 * Cuida do tédio comum: contexto, DPR (≤2), redimensionamento por
 * `ResizeObserver`, laço de animação, pausa quando a aba sai de vista e
 * liberação no destruir. Cada viz só desenha dentro de `aoQuadro`.
 *
 * O que mudou em relação ao legado: as cores vêm dos tokens do Stratum, e não de
 * literais escuros fixos. O legado desenhava sobre `#1b2942` mesmo no tema
 * claro — o gráfico era uma mancha escura no meio de uma tela clara.
 *
 * A cena é **sempre clara**, nos dois temas do app: uma folha com tinta escura,
 * como a figura impressa que ela imita. Escurecer o desenho junto com o app
 * apagava as figuras — e é do lado claro dos tokens que vem toda a paleta (ver
 * `corDoTema`).
 */

/** O que a viz recebe a cada quadro. `L`/`A` em px de CSS, `t` em segundos. */
export interface Quadro {
  readonly L: number;
  readonly A: number;
  readonly t: number;
}

export interface OpcoesCanvas2d {
  aoQuadro(ctx: CanvasRenderingContext2D, quadro: Quadro): void;
  /** Cor de fundo; `null` mantém o canvas transparente. */
  readonly fundo?: string | null;
}

/** O controle que toda viz devolve para a tela que a hospeda. */
export interface Viz {
  aplicar?(estado: Readonly<Record<string, unknown>>): void;
  redimensionar(): void;
  pausar(): void;
  retomar(): void;
  destruir(): void;
}

export function criarCanvas2d(canvas: HTMLCanvasElement, opcoes: OpcoesCanvas2d): Viz {
  const contexto = canvas.getContext('2d');
  if (contexto === null) throw new Error('canvas 2d indisponível');
  // Anotado à mão: o estreitamento do `if` não atravessa as funções abaixo.
  const ctx: CanvasRenderingContext2D = contexto;

  const inicio = performance.now();
  let quadroPendente: number | undefined;
  let pausado = false;
  let L = 1;
  let A = 1;

  function redimensionar(): void {
    const dpr = Math.min(devicePixelRatio || 1, 2);
    L = Math.max(canvas.clientWidth, 1);
    A = Math.max(canvas.clientHeight, 1);
    canvas.width = Math.round(L * dpr);
    canvas.height = Math.round(A * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function laco(): void {
    quadroPendente = requestAnimationFrame(laco);
    if (pausado) return;

    const t = (performance.now() - inicio) / 1000;
    ctx.clearRect(0, 0, L, A);

    const fundo = opcoes.fundo === undefined ? corDoTema('--st-color-neutral-50') : opcoes.fundo;
    if (fundo !== null) {
      ctx.fillStyle = fundo;
      ctx.fillRect(0, 0, L, A);
    }

    opcoes.aoQuadro(ctx, { L, A, t });
  }

  redimensionar();
  const observador = new ResizeObserver(() => redimensionar());
  observador.observe(canvas);

  const aoTrocarVisibilidade = (): void => {
    pausado = document.hidden;
  };
  document.addEventListener('visibilitychange', aoTrocarVisibilidade);

  laco();

  return {
    redimensionar,
    pausar() {
      pausado = true;
    },
    retomar() {
      pausado = false;
    },
    destruir() {
      if (quadroPendente !== undefined) cancelAnimationFrame(quadroPendente);
      quadroPendente = undefined;
      observador.disconnect();
      document.removeEventListener('visibilitychange', aoTrocarVisibilidade);
    },
  };
}

// ── Helpers de desenho ──────────────────────────────────────────────────────

/** Seta de (x0,y0) a (x1,y1), com cabeça. */
export function seta(
  ctx: CanvasRenderingContext2D,
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  cor: string,
  largura = 2,
): void {
  const angulo = Math.atan2(y1 - y0, x1 - x0);
  const cabeca = 9 + largura;

  ctx.strokeStyle = cor;
  ctx.fillStyle = cor;
  ctx.lineWidth = largura;

  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - cabeca * Math.cos(angulo - 0.4), y1 - cabeca * Math.sin(angulo - 0.4));
  ctx.lineTo(x1 - cabeca * Math.cos(angulo + 0.4), y1 - cabeca * Math.sin(angulo + 0.4));
  ctx.closePath();
  ctx.fill();
}

const cache = new Map<string, string>();

/**
 * A sonda que resolve os tokens.
 *
 * `color-scheme: light` fixo: os tokens do Stratum são `light-dark(claro,
 * escuro)`, e é o esquema de cores DA SONDA que decide qual dos dois sai. Fixá-lo
 * no claro é o que mantém a cena 2D como folha clara com tinta escura nos dois
 * temas do app.
 */
function criarSonda(): HTMLElement {
  const sonda = document.createElement('span');
  sonda.style.cssText =
    'position:absolute;width:0;height:0;visibility:hidden;pointer-events:none;color-scheme:light';
  document.documentElement.append(sonda);
  return sonda;
}

let sonda: HTMLElement | undefined;

/**
 * Lê uma cor do tema (um token do Stratum, como `--st-color-primary-600`) já
 * resolvida em algo que o canvas aceite.
 *
 * O caminho óbvio — `getComputedStyle(raiz).getPropertyValue(token)` — devolve o
 * texto CRU da custom property, e os tokens do Stratum são
 * `light-dark(#292929,#f1f1f1)`. Atribuir isso a `fillStyle` **não é erro**: o
 * canvas ignora o valor inválido em silêncio e continua desenhando com a cor
 * anterior. Era por isso que os textos saíam da cor do próprio fundo, invisíveis.
 * Quem sabe resolver `light-dark()` (e qualquer `var()` encadeada) é o navegador,
 * então a leitura passa por uma sonda: `color: var(--token)` entra, `rgb(...)`
 * sai.
 *
 * `getComputedStyle` força layout e uma viz chama isto muitas vezes por quadro;
 * o cache é por token e vale para sempre — a resposta não depende mais do tema
 * do app.
 */
export function corDoTema(token: string, reserva = '#888888'): string {
  const guardada = cache.get(token);
  if (guardada !== undefined) return guardada;

  // O texto cru não serve para pintar, mas serve para saber se o token existe:
  // um `var()` sem valor cai na herança, e a sonda devolveria a cor de outra
  // coisa em vez da reserva.
  const existe = getComputedStyle(document.documentElement).getPropertyValue(token).trim() !== '';

  sonda ??= criarSonda();
  sonda.style.color = `var(${token})`;

  const cor = existe ? getComputedStyle(sonda).color : reserva;
  cache.set(token, cor);
  return cor;
}
